/**
 * Composer dependency lockfile guard (PreToolUse).
 *
 * composer.lock is generated by Composer; direct edits (via write tools or
 * shell redirection) detach resolved dependency state from its generator and
 * make installs non-reproducible.
 *
 * Failure mode: fail-closed (deny) with a blocking contract.
 */

import { basename } from "node:path";
import { stringInput } from "../lib/composer-utils.mjs";

export const LOCKFILE_NAMES = ["composer.lock"];

function cleanPath(filePath) {
  return String(filePath ?? "").replaceAll("\\", "/").replace(/\/+$/u, "");
}

function isDependencyLockfile(filePath) {
  const cleaned = cleanPath(filePath);
  if (!cleaned) return false;
  const name = basename(cleaned);
  return LOCKFILE_NAMES.includes(name.toLowerCase());
}

function dependencyLockfileTargets(targets) {
  return [...new Set(targets.filter((target) => isDependencyLockfile(target)))];
}

const WRAPPER_TOKENS = new Set(["command", "corepack", "time"]);

function stripQuotes(token) {
  if (
    (token.startsWith("'") && token.endsWith("'")) ||
    (token.startsWith('"') && token.endsWith('"'))
  ) {
    return token.slice(1, -1);
  }
  return token;
}

function tokenize(segment) {
  return segment.match(/"[^"]*"|'[^']*'|\S+/gu)?.map(stripQuotes) ?? [];
}

function commandSegments(command) {
  return command.split(/&&|\|\||[;|\n]/u).map((segment) => segment.trim()).filter(Boolean);
}

function stripWrappers(tokens) {
  const result = [...tokens];
  while (result.length > 0) {
    const head = result[0] ?? "";
    if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(head)) {
      result.shift();
      continue;
    }
    if (head === "env") {
      result.shift();
      continue;
    }
    if (WRAPPER_TOKENS.has(head)) {
      result.shift();
      continue;
    }
    break;
  }
  return result;
}

/** Shell write targets for dependency lockfiles (redirects, tee, rm, mv, cp, sed -i ...). */
export function shellDependencyLockfileWriteTargets(command) {
  const targets = [];
  for (const match of command.matchAll(/(?<![0-9])>>?\s*(?:"([^"]+)"|'([^']+)'|([^\s;&|]+))/gu)) {
    targets.push(match[1] ?? match[2] ?? match[3] ?? "");
  }

  for (const segment of commandSegments(command)) {
    const tokens = stripWrappers(tokenize(segment));
    const tool = tokens[0];
    if (!tool) continue;

    if (tool === "tee") {
      targets.push(...tokens.slice(1).filter((token) => !token.startsWith("-")));
      continue;
    }

    if (["rm", "touch", "truncate"].includes(tool)) {
      targets.push(...tokens.slice(1).filter((token) => !token.startsWith("-")));
      continue;
    }

    if (tool === "mv") {
      targets.push(...tokens.slice(1).filter((token) => !token.startsWith("-")));
      continue;
    }

    if (["cp", "install"].includes(tool)) {
      const destination = [...tokens].reverse().find((token) => !token.startsWith("-"));
      if (destination && destination !== tool) targets.push(destination);
      continue;
    }

    if (tool === "sed" && tokens.some((token) => /^-.*i/u.test(token))) {
      targets.push(...tokens.slice(1).filter((token) => isDependencyLockfile(token)));
    }
  }

  return dependencyLockfileTargets(targets);
}

function canonicalToolName(toolName) {
  if (typeof toolName !== "string") return "";
  const lower = toolName.trim().toLowerCase();
  const map = {
    apply_patch: "ApplyPatch",
    applypatch: "ApplyPatch",
    write: "Write",
    edit: "Edit",
    multiedit: "MultiEdit",
    bash: "Bash",
    shell: "Shell",
    shell_command: "Shell",
    exec_command: "Shell",
    exec: "Shell",
    local_shell: "Shell",
    create_file: "Write",
    search_replace: "Edit",
  };
  return map[lower] || toolName;
}

function pathsFromPatch(patch) {
  if (typeof patch !== "string") return [];
  const paths = [];
  for (const line of patch.split("\n")) {
    const m = line.match(/^\*\*\*\s+(?:Add|Update|Delete) File:\s+(.+)$/);
    if (m) paths.push(m[1].trim());
  }
  return paths;
}

export function collectLockfileTargets({ toolName, input }) {
  const fileTargets = [];
  const name = canonicalToolName(toolName);

  switch (name) {
    case "Write":
    case "Edit":
    case "MultiEdit":
      if (input.file_path) fileTargets.push(input.file_path);
      if (Array.isArray(input.edits)) {
        if (input.path) fileTargets.push(input.path);
      }
      break;
    case "ApplyPatch": {
      if (input.file_path) fileTargets.push(input.file_path);
      if (input.path) fileTargets.push(input.path);
      const blob = [input.patch, input.input, input.command].filter(Boolean).join("\n");
      fileTargets.push(...pathsFromPatch(blob));
      break;
    }
    case "Bash":
    case "Shell": {
      const command = stringInput(input.command ?? input.cmd);
      return shellDependencyLockfileWriteTargets(command);
    }
    default:
      break;
  }

  return dependencyLockfileTargets(fileTargets);
}

export function lockfileDenyMessage(targets) {
  return [
    "[PHP Dependency Lockfile Guard] 已拦截依赖 lock 文件修改",
    "",
    `目标：${targets.join(", ")}`,
    "",
    "lock 文件由 Composer 生成，AI 不得直接编辑或通过 shell 写入。",
    "如确需变更依赖，请让用户明确授权依赖更新流程，并通过 Composer 重新生成 lock 文件。",
    "",
    "blockingContract:",
    "  observedFacts: 提议的输入直接写入 composer.lock，或通过 shell 写入操作指向 composer.lock。",
    "  harm: 直接编辑 Composer 生成的 lockfile 会使解析后的依赖状态脱离其生成器，导致后续安装不可复现。",
    "  unblockWhen: 提议的输入不再写入 composer.lock，或依赖变更通过 Composer 完成。",
    "  recovery: 修改依赖声明，用 Composer 重新生成 lockfile，然后重试原操作。",
  ].join("\n");
}
